<script setup>
import {ref,watch} from 'vue';
import {api,scope,state,can,ask,notify} from '../lib/workspace';
import {dateTime} from '../lib/format';
const emit=defineEmits(['cleaned']);
const opened=ref(false),packages=ref([]),settings=ref({enabled:false,retention_days:1825,interval_hours:24,mode:'hide_history'}),selected=ref([]),mode=ref('hide_history'),preview=ref(null),busy=ref(false),error=ref(''),result=ref(null);let sequence=0;
watch(()=>state.companyId,()=>{sequence++;opened.value=false;packages.value=[];selected.value=[];preview.value=null;result.value=null;busy.value=false;error.value='';settings.value={enabled:false,retention_days:1825,interval_hours:24,mode:'hide_history'};});
watch([selected,mode],()=>{preview.value=null;result.value=null;},{deep:true,flush:'sync'});
function blockedReasons(p){return mode.value==='hide_history'?(p.history_hidden?['history_already_hidden']:[]):(p.blocked_reasons||[]);}
async function restoreHistory(p){if(busy.value)return;const cid=state.companyId,seq=sequence;if(!await ask({title:'Restaurar histórico?',message:`Reexibir ${p.filename} no histórico. Esta ação não recupera arquivos que já tenham sido removidos.`,confirmLabel:'Restaurar histórico'}))return;if(seq!==sequence||cid!==state.companyId)return;busy.value=true;error.value='';try{await api(scope('/import-packages/restore-history',cid),{method:'POST',body:{ids:[p.id]}});if(seq!==sequence)return;emit('cleaned');busy.value=false;await load();notify('Histórico restaurado.');}catch(e){if(seq===sequence)error.value=e.message;}finally{if(seq===sequence)busy.value=false;}}
function bytes(value){return `${Number(value||0).toLocaleString('pt-BR')} bytes`;}
async function load(){if(busy.value)return;const seq=++sequence,cid=state.companyId;busy.value=true;error.value='';try{const data=await api(scope('/import-packages',cid));if(seq!==sequence||cid!==state.companyId)return;packages.value=data.packages||[];settings.value={enabled:false,retention_days:1825,interval_hours:24,mode:'hide_history',...data.settings};opened.value=true;}catch(e){if(seq===sequence)error.value=e.message;}finally{if(seq===sequence)busy.value=false;}}
async function saveSettings(){if(busy.value)return;const cid=state.companyId,seq=sequence,body={...settings.value};if(!Number.isInteger(Number(body.retention_days))||Number(body.retention_days)<1||!Number.isInteger(Number(body.interval_hours))||Number(body.interval_hours)<1){error.value='Informe retenção e intervalo inteiros maiores que zero.';return;}
 if(body.enabled&&body.mode!=='hide_history'){if(!await ask({title:'Habilitar limpeza periódica de pacotes?',message:`Após ${body.retention_days} dias desde a criação do pacote, verificar a cada ${body.interval_hours} horas e remover originais elegíveis${body.mode==='originals_and_hide_history'?' e ocultar seu histórico':''}. A primeira verificação ocorrerá em até 60 segundos, inclusive sem esta tela aberta. A remoção dos arquivos é irreversível; download e DANFE poderão ficar indisponíveis. Documentos fiscais, lançamentos e movimentos gerados nunca serão excluídos.`,confirmLabel:'Habilitar limpeza periódica',danger:true}))return;body.acknowledge_irreversible=true;}
 if(body.enabled&&body.mode==='hide_history'&&!await ask({title:'Habilitar arquivamento periódico do histórico?',message:`Após ${body.retention_days} dias desde a criação do pacote, ocultar o histórico elegível a cada ${body.interval_hours} horas. A primeira verificação ocorrerá em até 60 segundos, inclusive sem esta tela aberta. Todos os arquivos e movimentos serão preservados; o histórico pode ser restaurado.`,confirmLabel:'Habilitar arquivamento'}))return;
 if(seq!==sequence||cid!==state.companyId)return;busy.value=true;error.value='';try{const saved=await api(scope('/import-packages/settings',cid),{method:'PUT',body});if(seq!==sequence)return;settings.value={...body,...saved};notify(body.enabled?'Retenção periódica configurada. Movimentos serão preservados.':'Limpeza periódica desativada.');}catch(e){if(seq===sequence)error.value=e.message;}finally{if(seq===sequence)busy.value=false;}}
async function prepareCleanup(){if(busy.value||!selected.value.length)return;const cid=state.companyId,seq=sequence,ids=[...selected.value],chosenMode=mode.value;busy.value=true;error.value='';try{const data=await api(scope('/import-packages/cleanup-preview',cid),{method:'POST',body:{ids,mode:chosenMode}});if(seq!==sequence||JSON.stringify(ids)!==JSON.stringify(selected.value)||chosenMode!==mode.value)return;preview.value=data;}catch(e){if(seq===sequence)error.value=e.message;}finally{if(seq===sequence)busy.value=false;}}
async function confirmCleanup(){if(busy.value||!preview.value?.eligible_ids?.length)return;const cid=state.companyId,seq=sequence,p=preview.value,body={ids:[...selected.value],mode:mode.value,preview_hash:p.preview_hash,...(mode.value==='hide_history'?{}:{acknowledge_irreversible:true})};if(mode.value==='hide_history'){if(!await ask({title:'Arquivar histórico dos pacotes?',message:`Ocultar ${p.eligible_ids.length} pacote(s) do histórico. Todos os arquivos, documentos e movimentos serão preservados; a economia de espaço é zero. Você pode restaurar o histórico.`,confirmLabel:'Arquivar somente histórico'}))return;}else if(!await ask({title:'Remover arquivos dos pacotes selecionados?',message:`${p.eligible_ids.length} pacote(s) elegível(is), aproximadamente ${bytes(p.estimated_bytes)}. Originais removidos não poderão ser baixados e sua representação DANFE pode ficar indisponível. ${body.mode==='originals_and_hide_history'?'O histórico elegível também será ocultado. ':''}Esta remoção de arquivos é irreversível. Documentos, lançamentos, movimentos e vínculos serão preservados.`,confirmLabel:'Limpar somente pacotes',danger:true}))return;
 if(seq!==sequence||p!==preview.value||cid!==state.companyId)return;busy.value=true;error.value='';try{const data=await api(scope('/import-packages/cleanup-confirm',cid),{method:'POST',body});if(seq!==sequence)return;result.value=data;preview.value=null;selected.value=[];emit('cleaned');notify('Limpeza de pacotes concluída. Movimentos preservados.');busy.value=false;await load();result.value=data;}catch(e){if(seq===sequence)error.value=e.message;}finally{if(seq===sequence)busy.value=false;}}
</script>
<template><section class="panel panel-body"><button class="button outline" :disabled="busy" @click="opened=!opened;opened&&load()">Pacotes e retenção de arquivos</button><p v-if="error" class="message error" role="alert">{{error}}</p><template v-if="opened"><h3>Limpeza de pacotes, sem excluir movimentos</h3><p>Remove somente arquivos elegíveis e, quando escolhido, oculta o histórico do pacote. Documentos, lançamentos, movimentos e vínculos permanecem preservados. Evidências protegidas não são removidas. Arquivar somente o histórico preserva todos os bytes e é reversível, inclusive para pacotes fiscais. A remoção de arquivos continua bloqueada quando o pacote é a única evidência fiscal.</p><form @submit.prevent="saveSettings"><div class="form-grid"><label class="inline-choice"><input v-model="settings.enabled" type="checkbox" :disabled="busy||!can('fiscal.imports','delete')"/>Habilitar limpeza periódica (desativada por padrão)</label><label>Retenção mínima em dias<input v-model.number="settings.retention_days" type="number" min="1" step="1" required :disabled="busy"/></label><label>Intervalo entre verificações (horas)<input v-model.number="settings.interval_hours" type="number" min="1" step="1" required :disabled="busy"/></label><label>Ação periódica<select v-model="settings.mode" :disabled="busy"><option value="hide_history">Arquivar histórico (preservar todos os arquivos)</option><option value="originals">Remover arquivos originais</option><option value="originals_and_hide_history">Remover originais e ocultar histórico elegível</option></select></label></div><p class="field-help">Última execução: {{dateTime(settings.last_run)}}. A idade é contada desde a criação do pacote. A política só muda após salvar; quando habilitada, executa sem esta tela aberta e faz a primeira verificação em até 60 segundos.</p><button v-if="can('fiscal.imports','delete')" class="button outline" :disabled="busy">Salvar política de retenção</button></form><h4>Limpeza manual com prévia</h4><label>Ação para os pacotes selecionados<select v-model="mode" :disabled="busy"><option value="hide_history">Arquivar histórico (preservar todos os arquivos)</option><option value="originals">Remover arquivos originais</option><option value="originals_and_hide_history">Remover originais e ocultar histórico elegível</option></select></label><div class="table-scroll"><table><thead><tr><th>Selecionar</th><th>Pacote</th><th>Data</th><th>Espaço</th><th>Disponibilidade / bloqueios</th></tr></thead><tbody><tr v-for="p in packages" :key="p.id"><td><input v-model="selected" type="checkbox" :value="p.id" :disabled="busy||blockedReasons(p).length>0||(mode==='hide_history'?p.history_hidden:(!p.available&&(mode==='originals'||p.history_hidden)))" :aria-label="`Selecionar pacote ${p.filename}`"/></td><td>{{p.filename}}</td><td>{{dateTime(p.created_at)}}</td><td>{{bytes(p.original_bytes)}}</td><td>{{p.available?'Original disponível':'Original indisponível'}}{{p.history_hidden?' · Histórico oculto':''}}<small class="cell-secondary">{{blockedReasons(p).map(reason=>reason==='sole_fiscal_source_evidence'?'Única evidência de origem fiscal: preservada':reason).join(' · ')}}</small><button v-if="p.history_hidden&&can('fiscal.imports','delete')" type="button" class="text-button" :disabled="busy" @click="restoreHistory(p)">Restaurar histórico</button></td></tr></tbody></table></div><button v-if="can('fiscal.imports','delete')" class="button outline" :disabled="busy||!selected.length" @click="prepareCleanup">Conferir prévia da limpeza</button><section v-if="preview" class="panel-body"><p>{{preview.eligible_ids?.length||0}} pacotes elegíveis · {{preview.blocked_ids?.length||0}} bloqueados · {{bytes(preview.estimated_bytes)}}</p><p v-for="(warning,index) in preview.warnings||[]" :key="index" class="message warning">{{warning}}</p><button class="button primary" :disabled="busy||!preview.eligible_ids?.length" @click="confirmCleanup">{{mode==='hide_history'?'Arquivar somente histórico':'Confirmar limpeza somente dos pacotes'}}</button></section><p v-if="result" class="message success">Pacotes processados. Documentos, lançamentos e movimentos preservados.</p></template></section></template>
